let qty = 1;
function changeQty(d) {
  qty = Math.max(1, qty + d);
  const el = document.getElementById('qty-display');
  if(el) el.textContent = qty;
}
function selectGrind(btn) {
  btn.closest('.grind-options').querySelectorAll('.grind-opt').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
}

// ===== CART =====
function addToCart(name, price) {
  const existing = cart.find(i=>i.name===name);
  if(existing) existing.qty++;
  else cart.push({name, price, qty: 1});
  updateCartCount();
  showToast(`☕ ${name} añadido al carrito`);
}

function updateCartCount() {
  const total = cart.reduce((s,i)=>s+i.qty,0);
  document.getElementById('cart-count').textContent = total;
}

function renderCart() {
  const list = document.getElementById('cart-items-list');
  if(cart.length === 0) {
    list.innerHTML = `<div style="text-align:center;padding:80px 0;color:#9ca3af;">
      <div style="font-size:60px;margin-bottom:16px;">🛒</div>
      <div style="font-size:18px;font-weight:600;margin-bottom:8px;">Tu carrito está vacío</div>
      <div style="margin-bottom:24px;">Añade productos para continuar</div>
      <button class="btn-primary" onclick="navigate('tienda')">Ver tienda →</button>
    </div>`;
  } else {
    list.innerHTML = cart.map((item,i) => `
      <div class="cart-item">
        <div class="cart-item-img"><img src="data:image/webp;base64," alt="${item.name}"></div>
        <div>
          <div class="cart-item-name">${item.name}</div>
          <div class="cart-item-detail">250g · Grano entero</div>
          <div class="qty-control" style="transform:scale(0.85);transform-origin:left;">
            <button class="qty-btn" onclick="updateCartQty(${i},-1)">−</button>
            <span class="qty-num">${item.qty}</span>
            <button class="qty-btn" onclick="updateCartQty(${i},1)">+</button>
          </div>
        </div>
        <div style="text-align:right;">
          <div style="font-family:'Fredoka',sans-serif;font-size:24px;color:var(--blue);margin-bottom:8px;">${(item.price*item.qty).toFixed(2).replace('.',',')}€</div>
          <button onclick="removeFromCart(${i})" style="background:none;border:none;color:#9ca3af;font-size:12px;cursor:none;text-decoration:underline;">Eliminar</button>
        </div>
      </div>
    `).join('');
  }
  updateCartSummary();
}

function updateCartQty(i, d) {
  cart[i].qty = Math.max(1, cart[i].qty + d);
  updateCartCount();
  renderCart();
}

function removeFromCart(i) {
  cart.splice(i,1);
  updateCartCount();
  renderCart();
}

function updateCartSummary() {
  const sub = cart.reduce((s,i)=>s+i.price*i.qty, 0);
  const disc = discountApplied ? sub * 0.1 : 0;
  const total = sub - disc;
  document.getElementById('cart-subtotal').textContent = sub.toFixed(2).replace('.',',')+'€';
  document.getElementById('cart-discount').textContent = disc > 0 ? '-'+disc.toFixed(2).replace('.',',')+'€' : '—';
  document.getElementById('cart-total').textContent = total.toFixed(2).replace('.',',')+'€';
}

function applyCoupon() {
  const code = document.getElementById('coupon-field').value.toUpperCase();
  if(code === 'BLAU10') {
    discountApplied = true;
    renderCart();
    showToast('✅ Código BLAU10 aplicado. 10% de descuento!');
  } else {
    showToast('❌ Código no válido');
  }
}

function renderCheckout() {
  const items = document.getElementById('checkout-items');
  const totalEl = document.getElementById('checkout-total');
  const sub = cart.reduce((s,i)=>s+i.price*i.qty, 0);
  items.innerHTML = cart.map(i=>`
    <div class="summary-row" style="align-items:center;">
      <span style="font-size:14px;">${i.name} ×${i.qty}</span>
      <span style="font-weight:600;">${(i.price*i.qty).toFixed(2).replace('.',',')}€</span>
    </div>
  `).join('') || '<div style="color:#9ca3af;font-size:14px;text-align:center;padding:20px;">Carrito vacío</div>';
  totalEl.textContent = sub.toFixed(2).replace('.',',')+'€';
}

function confirmOrder() {
  if(cart.length === 0) { showToast('⚠️ Tu carrito está vacío'); return; }
  const num = 'BLAU-2025-' + String(Math.floor(Math.random()*9000)+1000);
  document.getElementById('order-number').textContent = 'Pedido #' + num;
  cart = [];
  updateCartCount();
  navigate('confirmacion');
}

function selectPayment(el) {
  document.querySelectorAll('.payment-method').forEach(m=>m.classList.remove('active'));
  el.classList.add('active');
}

// ===== FILTERS =====
function setFilter(btn, filter) {
  document.querySelectorAll('.filter-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  renderShop(filter);
}

// ===== FAQ =====
function toggleFAQ(el) {
  const item = el.closest('.faq-item');
  const wasOpen = item.classList.contains('open');
  document.querySelectorAll('.faq-item').forEach(f=>f.classList.remove('open'));
  if(!wasOpen) item.classList.add('open');
}

// ===== AI RECOMMENDER =====
function toggleAI(btn) { btn.classList.toggle('selected'); }
function showAIResult() {
  document.getElementById('ai-result').classList.add('visible');
}

// ===== POPUP =====
function closePopup() {
  document.getElementById('welcome-popup').classList.remove('visible');
}

// ===== TOAST =====
function showToast(msg) {
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  setTimeout(()=>t.classList.remove('show'), 3000);
}

// ===== CURSOR =====
const cursor = document.getElementById('cursor');
const ring = document.getElementById('cursor-ring');
let rx=0, ry=0;
document.addEventListener('mousemove', e => {
  cursor.style.left = e.clientX + 'px';
  cursor.style.top = e.clientY + 'px';
  rx += (e.clientX - rx) * 0.15;
  ry += (e.clientY - ry) * 0.15;
  ring.style.left = e.clientX + 'px';
  ring.style.top = e.clientY + 'px';
});
document.querySelectorAll('button, a, [onclick]').forEach(el => {
  el.addEventListener('mouseenter', ()=>{ cursor.style.width='20px';cursor.style.height='20px'; ring.style.width='60px';ring.style.height='60px'; });
  el.addEventListener('mouseleave', ()=>{ cursor.style.width='12px';cursor.style.height='12px'; ring.style.width='40px';ring.style.height='40px'; });
});

// ===== LOADER =====
window.addEventListener('load', () => {
  setTimeout(()=>{
    document.getElementById('loader').classList.add('hidden');
    setTimeout(()=>{ document.getElementById('welcome-popup').classList.add('visible'); }, 800);
  }, 2000);
});

// ===== NAV SCROLL =====
window.addEventListener('scroll', ()=>{
  document.getElementById('main-nav').classList.toggle('scrolled', window.scrollY > 50);
});

// ===== SCROLL REVEAL =====
const observer = new IntersectionObserver((entries) => {
  entries.forEach(e => { if(e.isIntersecting) e.target.classList.add('visible'); });
}, {threshold: 0.1});
document.querySelectorAll('.reveal').forEach(el => observer.observe(el));

// ===== INIT =====
renderShop();